function validate([queries, intLength]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 50000) return 'queries needs 1 to 5 * 10^4 values.';
  if (queries.some(q => !Number.isInteger(q) || q < 1 || q > 1e9)) return 'Each query is an integer between 1 and 10^9.';
  if (!Number.isInteger(intLength) || intLength < 1 || intLength > 15) return 'intLength is between 1 and 15.';
  return null;
}

