function kthPalindrome(queries, intLength) {
  const halfLength = Math.ceil(intLength / 2);
  const first = 10 ** (halfLength - 1);
  const total = 9 * first;
  const answer = [];

  for (const query of queries) {
    if (query > total) {
      answer.push(-1);
      continue;
    }
    let palindrome = first + query - 1;
    let rest = intLength % 2 === 0 ? palindrome : Math.floor(palindrome / 10);
    while (rest > 0) {
      palindrome = palindrome * 10 + (rest % 10);
      rest = Math.floor(rest / 10);
    }
    answer.push(palindrome);
  }
  return answer;
}

