function kthPalindrome(queries, intLength) {
  const half = Math.ceil(intLength / 2);
  // Short lengths: list every intLength-digit number that reads the same both ways.
  let list = null;
  if (intLength <= 5) {
    list = [];
    for (let x = 10 ** (intLength - 1); x < 10 ** intLength; x++) {
      const text = String(x);
      if (text === [...text].reverse().join('')) list.push(x);
    }
  }
  return queries.map(query => {
    if (list) return query <= list.length ? list[query - 1] : -1;
    // Longer lengths: choose the front digits one by one; each choice covers a block of palindromes.
    let rank = query - 1;
    const digits = [];
    for (let pos = 0; pos < half; pos++) {
      const block = 10 ** (half - pos - 1);
      const digit = (pos === 0 ? 1 : 0) + Math.floor(rank / block);
      if (digit > 9) return -1;
      digits.push(digit);
      rank %= block;
    }
    return Number(digits.concat(digits.slice(0, intLength - half).reverse()).join(''));
  });
}

