function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const intLength = size === 'large' || rand() < 0.25 ? int(1, 15) : int(1, 5);
  const total = 9 * 10 ** (Math.ceil(intLength / 2) - 1);
  const count = size === 'large' ? int(1500, 2000) : int(1, 6);
  const queries = [];
  for (let i = 0; i < count; i++) {
    const r = rand();
    if (r < 0.1) queries.push(1);
    else if (r < 0.2) queries.push(Math.min(total, 1e9));
    else if (r < 0.3) queries.push(Math.min(total + 1, 1e9));
    else if (r < 0.4) queries.push(int(1, 1e9));
    else if (r < 0.45) queries.push(1e9);
    else queries.push(int(1, Math.min(total, 1e9)));
  }
  return [queries, intLength];
}
